import { readFileSync } from "node:fs";
const LOG = process.argv[2];
const raw = readFileSync(LOG, "utf8");
const lines = raw.split("\n").filter((l) => l.trim().length > 0);
const records = lines.map((l) => JSON.parse(l));
const CLASSES = new Set(["policy.edit", "log.advance"]);
const byTask = new Map();
for (const r of records) {
  if (r.seq < 5147) continue;
  const task = r.task;
  if (task === undefined) continue;
  if (!byTask.has(task)) byTask.set(task, []);
  byTask.get(task).push(r);
}
const rows = [];
for (const [task, recs] of byTask.entries()) {
  recs.sort((a, b) => a.seq - b.seq);
  let cls = null;
  for (const r of recs) {
    if (r.event === "task.registered" && Array.isArray(r.payload?.actions)) {
      for (const a of r.payload.actions) if (CLASSES.has(a.class)) cls = a.class;
    }
    if (r.payload?.class && CLASSES.has(r.payload.class)) cls = r.payload.class;
  }
  if (cls === null) continue;
  rows.push({ task, cls, minSeq: recs[0].seq, maxSeq: recs[recs.length-1].seq, events: recs.map(r=>r.event) });
}
rows.sort((a,b)=>a.minSeq-b.minSeq);
for (const r of rows) console.log(r.minSeq, r.maxSeq, r.cls, r.task, r.events.join(","));
EOF
